                pts = [(r, c) for r, c in sevens
                       if r != hr and c != vc
                       and (r < hr if upper else r > hr)
                       and (c < vc if left else c > vc)]
                if pts:
                    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
                    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
                    move(pts, -r0 if upper else h - 1 - r1,
                         -c0 if left else w - 1 - c1)
    elif vm:
        top = vm[0] == 0
        for left in (True, False):
            pts = [(r, c) for r, c in sevens if c != vc and (c < vc if left else c > vc)]
            if pts:
