                c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
                move(pts, -r0 if upper else h - 1 - r1,
                     -c0 if left_edge else w - 1 - c1)

    if vm:
        aligned = [r for r, c in sevens if c == vc]
        if aligned:
            end = max(aligned) if vm[0] == 0 else min(aligned)
            for r in (range(0, end + 1) if vm[0] == 0 else range(end, h)):
                if grid[r][vc] != 7:
